def describe(r):
    name, ref = r['title'], r.get('reference_block','')
    if name in SPECIAL: return SPECIAL[name]
    if r['kind'] == 'system':
        if name in AREA: return AREA[name][1]
        return f"{name} is a nested view within {r['area']}. It exposes the component connections and named channels used by this part of the model. " + AREA.get(r['area'],('', ''))[1]
    if 'ThreePhaseVIMeasurement' in ref: return f"{name} measures three-phase voltage and current at this drawn boundary. The signals feed the measurement/protection path. The active model uses ideal measurement; CT saturation and VT error are not simulated."
    if 'ThreePhaseFault' in ref: return f"{name} is a switched fault branch at this location. The selected study applies its requested phase/earth connection and timing to the physical AC network. Its fault resistance and schedule are study inputs; it is not normal operating plant equipment."
    if 'PISectionLine' in ref: return f"{name} is one half of a modeled transmission circuit. A PI equivalent represents series resistance/inductance and shunt capacitance. Four such sections represent two parallel circuits with a midpoint available for a fault."
    if 'spsGroundLib' in ref: return f"{name} provides an electrical reference/earth connection in this equivalent circuit. A nearby neutral resistor determines whether the represented return is resistively grounded."
    if 'CurrentMeasurement' in ref: return f"{name} measures current in its connected physical branch and outputs a data signal for processing."
    if r['block_type'] in TYPES: return TYPES[r['block_type']][1]
    return r.get('description') or f"Actual exported {r['block_type']} block in {r['area']}; read its parent snapshot to place it in the circuit or signal path."

def link(identifier, label=None):
    r = BY_ID[identifier]
    return f'<a href="#component-{identifier}" class="ref-link">{e(label or r["title"])} <span>↗</span></a>'

def figure(identifier, caption):
    r = BY_ID[identifier]
    return f'<figure><a href="{e(r["image"])}" target="_blank" rel="noopener"><img src="{e(r["image"])}" alt="{e(r["title"])} — actual Simulink export" loading="lazy"></a><figcaption>{e(caption)} · {link(identifier,"Snapshot "+identifier)}</figcaption></figure>'

