sections.append('''<section id="catalog"><span class="kicker">09 / Whole SLD & Subsystem Catalog</span><h2>Whole SLD & Subsystem Reference</h2><p>All '''+str(systems)+''' system views: the complete plant SLD overview and all operational subsystems. Search a subsystem name, busbar ID, area or model path. Expand a row to see its role, exact location and actual snapshot.</p><div class="toolbar"><label>Search<input id="search" type="search" placeholder="Try Switchyard, Generator, B_22, Protection…" autocomplete="off"></label><label>Area<select id="area"><option value="">All areas</option>'''+''.join(f'<option>{e(a)}</option>' for a in areas)+'''</select></label></div><div class="catalog-count"><span id="count">'''+str(systems)+''' of '''+str(systems)+''' system views</span><button type="button" id="clear">Clear filters</button></div><p class="screen-note">Original PNG links open at full size. The annotated gallery provides the PDF-supported facts and additions alongside each image. Search runs entirely in this file; no server or internet connection is required.</p><div id="entries">'''+''.join(entries)+'''</div><p class="empty" id="empty">No matching system views. Try a shorter name or clear the area filter.</p><noscript><p>JavaScript is disabled. All entries remain available; use your browser’s Find command and expand the rows.</p></noscript></section>''')

script = '''const search=document.getElementById('search'),area=document.getElementById('area'),entries=[...document.querySelectorAll('#entries .entry')];function filter(){const words=search.value.trim().toLowerCase().split(/\\s+/).filter(Boolean);let n=0;for(const item of entries){const show=(!area.value||item.dataset.area===area.value)&&words.every(word=>item.dataset.search.includes(word));item.hidden=!show;if(show)n++;}document.getElementById('count').textContent=n+' of '+entries.length+' system views';document.getElementById('empty').style.display=n?'none':'block';}search.addEventListener('input',filter);area.addEventListener('change',filter);document.getElementById('clear').addEventListener('click',()=>{search.value='';area.value='';filter();search.focus();});function revealHash(){const id=decodeURIComponent(location.hash.slice(1));const item=document.getElementById(id);if(!item)return;if(id.startsWith('component-')){search.value='';area.value='';filter();item.open=true;}else if(id.startsWith('source-area-')){item.open=true;}else{return;}requestAnimationFrame(()=>item.scrollIntoView({block:'start'}));}window.addEventListener('hashchange',revealHash);revealHash();'''
nav=[('read','01 · Read the model'),('power','02 · Power route'),('busbars','03 · Six busbars'),('subsystems','04 · Subsystem guide'),('parts','05 · Parts and block types'),('protection','06 · Protection sequence'),('dc','07 · DC and auxiliaries'),('sources','08 · Sources and additions'),('catalog','09 · Whole SLD & Subsystems')]
document = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Offline illustrated manual for the Ashuganj South v4 Simulink model: whole SLD and subsystem views."><title>Ashuganj South · Plant SLD & Subsystem Manual</title><style>'+css+'</style></head><body><header class="hero"><div class="wrap"><div class="eyebrow">Ashuganj South · Phase 6 · v4 presentation</div><h1>Understand every subsystem<br>and whole plant SLD.</h1><p>An illustrated guide to power flow, voltage levels, busbars, protection, whole plant SLD and subsystems—with a clear line from source documents to study choices.</p><div class="hero-links"><a href="index.html">Open snapshot gallery</a><a href="#catalog">Search all 24 system views</a><a href="../docs/SIMULINK_USER_MANUAL.html">Operating and settings manual</a></div><div class="pills"><span>Whole SLD (top level)</span><span>23 subsystem views</span><span>Six presentation bus IDs</span><span>Offline · 25 September 2026</span></div></div></header><div class="wrap layout"><nav aria-label="Manual contents"><strong>In this guide</strong>'+''.join(f'<a href="#{i}">{label}</a>' for i,label in nav)+'</nav><main>'+''.join(sections)+'</main></div><footer class="wrap">Generated from the actual exported model manifest. Keep this HTML with its raw snapshot folder, gallery and provenance files. <a href="manifest.json">Export manifest</a> · <a href="SOURCES_AND_ADDITIONS.md">Evidence register</a> · <a href="#read">Back to start</a></footer><script type="application/json" id="embedded-manifest">'+json.dumps(MANIFEST,ensure_ascii=False).replace('</','<\\/')+'</script><script>'+script+'</script></body></html>'
(ROOT/'manual.html').write_text(document,encoding='utf-8')
